<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { apiRequest } from '../lib/api';
import { myotaClient } from '../lib/myotaClient';
import { useAppStore } from '../stores/app';

interface TemplateElement { kind: string; label: string; x: number; y: number; width: number; height: number }
interface Award { id?: string; programmeSlug?: string; code: string; name: string; description?: string; category?: string; status?: string; achievementMetric?: string; condition?: unknown; levels?: unknown; effectiveFrom?: string; backgroundAsset?: Record<string, unknown>; printSpec?: Record<string, unknown>; template?: { elements?: TemplateElement[] } }

const store = useAppStore();
const programme = ref(store.currentProgramme || store.programmes[0]?.slug || '');
const items = ref<Award[]>([]); const selected = ref<Award | null>(null); const assets = ref<any[]>([]); const requests = ref<any[]>([]); const issuances = ref<any[]>([]); const message = ref('');
const templateElements = ref<TemplateElement[]>([]); const assetFile = ref<File | null>(null);
const dragState = ref<{ index: number; x: number; y: number } | null>(null);
const form = reactive({ code: '', name: '', description: '', category: 'HUNTER', achievementMetric: 'QSO_COUNT', effectiveFrom: '', condition: '{\n  "kind": "AND",\n  "conditions": [{ "kind": "QSO_COUNT", "operator": "GTE", "value": 10 }]\n}', levels: '[{ "id": "level-10", "name": "10 contacts", "threshold": 10 }]', backgroundKey: '', backgroundType: 'image/png', width: 2481, height: 3508, page: 'A4', orientation: 'PORTRAIT', dpi: 300 });
const assetForm = reactive({ kind: 'SIGNATURE', name: '', objectKey: '', mediaType: 'image/png', width: 1200, height: 400, sha256: '' });
const pageSizesMm: Record<string, [number, number]> = { A4: [210, 297], LETTER: [215.9, 279.4] };
const canvasAspectRatio = computed(() => { const [width, height] = pageSizesMm[form.page] || pageSizesMm.A4; return form.orientation === 'LANDSCAPE' ? `${height} / ${width}` : `${width} / ${height}`; });
watch([() => form.page, () => form.orientation], () => { document.documentElement.style.setProperty('--award-canvas-aspect', canvasAspectRatio.value); }, { immediate: true });
onUnmounted(() => document.documentElement.style.removeProperty('--award-canvas-aspect'));

function defaultElements(): TemplateElement[] { return [{ kind: 'AWARD_NAME', label: 'Award name', x: .25, y: .10, width: .50, height: .08 }, { kind: 'CALLSIGN', label: 'Callsign', x: .35, y: .34, width: .30, height: .08 }, { kind: 'PERSON_NAME', label: 'Participant name', x: .25, y: .45, width: .50, height: .08 }, { kind: 'DATE_OBTAINED', label: 'Date obtained', x: .35, y: .57, width: .30, height: .06 }, { kind: 'MANAGER_NAME', label: 'Award manager', x: .20, y: .79, width: .35, height: .06 }, { kind: 'MANAGER_SIGNATURE', label: 'Manager signature', x: .60, y: .73, width: .25, height: .14 }]; }
function edit(item: Award | null): void { selected.value = item; const background: any = item?.backgroundAsset || {}; const print: any = item?.printSpec || {}; templateElements.value = JSON.parse(JSON.stringify(item?.template?.elements || defaultElements())); Object.assign(form, { code: item?.code || '', name: item?.name || '', description: item?.description || '', category: item?.category || 'HUNTER', achievementMetric: item?.achievementMetric || 'QSO_COUNT', effectiveFrom: item?.effectiveFrom ? String(item.effectiveFrom).slice(0, 16) : '', condition: JSON.stringify(item?.condition || { kind: 'AND', conditions: [{ kind: 'QSO_COUNT', operator: 'GTE', value: 10 }] }, null, 2), levels: JSON.stringify(item?.levels || [{ id: 'level-10', name: '10 contacts', threshold: 10 }], null, 2), backgroundKey: background.objectKey || '', backgroundType: background.mediaType || 'image/png', width: background.widthPx || 2481, height: background.heightPx || 3508, page: print.page || 'A4', orientation: print.orientation || 'PORTRAIT', dpi: print.dpi || 300 }); }
function addTemplateElement(): void { templateElements.value.push({ kind: 'CUSTOM_TEXT', label: 'Custom text', x: .35, y: .25, width: .3, height: .06 }); }
function removeTemplateElement(index: number): void { templateElements.value.splice(index, 1); }
function beginDrag(event: PointerEvent, index: number): void { event.preventDefault(); (event.currentTarget as HTMLElement).setPointerCapture?.(event.pointerId); dragState.value = { index, x: event.clientX, y: event.clientY }; }
function moveDrag(event: PointerEvent): void { if (!dragState.value) return; const canvas = event.currentTarget as HTMLElement; const rect = canvas.getBoundingClientRect(); const element = templateElements.value[dragState.value.index]; if (!element) return; const deltaX = (event.clientX - dragState.value.x) / rect.width; const deltaY = (event.clientY - dragState.value.y) / rect.height; element.x = Math.max(0, Math.min(1 - element.width, element.x + deltaX)); element.y = Math.max(0, Math.min(1 - element.height, element.y + deltaY)); dragState.value.x = event.clientX; dragState.value.y = event.clientY; }
function endDrag(): void { dragState.value = null; }
async function load(selectedId?: string | Event): Promise<void> { if (!programme.value) return; const id = typeof selectedId === 'string' ? selectedId : undefined; const [awardData, assetData, requestData, issuanceData] = await Promise.all([apiRequest<{ items: Award[] }>(`/v1/awards?programme=${encodeURIComponent(programme.value)}&pageSize=100`), apiRequest<{ items: any[] }>('/v1/awards/assets?pageSize=100'), apiRequest<{ items: any[] }>('/v1/awards/requests?pageSize=100'), apiRequest<{ items: any[] }>('/v1/awards/issuances?pageSize=100')]); items.value = awardData.items || []; assets.value = assetData.items || []; requests.value = requestData.items || []; issuances.value = issuanceData.items || []; if (id) edit(items.value.find(item => item.id === id) || null); }
async function save(): Promise<void> { try { const saved = await apiRequest<Award>('/v1/awards', { method: 'POST', body: JSON.stringify({ awardId: selected.value?.id, programmeSlug: programme.value, code: form.code, name: form.name, description: form.description, category: form.category, achievementMetric: form.achievementMetric, condition: JSON.parse(form.condition), levels: JSON.parse(form.levels), backgroundAsset: { kind: 'BACKGROUND', name: `${form.name} background`, objectKey: form.backgroundKey, mediaType: form.backgroundType, widthPx: Number(form.width), heightPx: Number(form.height) }, printSpec: { page: form.page, orientation: form.orientation, dpi: Number(form.dpi) }, template: { elements: templateElements.value } }), headers: { 'Idempotency-Key': crypto.randomUUID() } }); message.value = 'Award draft saved.'; await load(saved.id); } catch (error) { message.value = error instanceof Error ? error.message : 'Invalid award definition.'; } }
async function action(actionName: string, decision?: string): Promise<void> { if (!selected.value?.id) return; try { if (actionName === 'publish' && !form.effectiveFrom) throw new Error('Choose an effective date before publishing.'); const body = actionName === 'review' ? { status: decision, reviewerId: store.account?.id } : actionName === 'publish' ? { status: 'PUBLISHED', effectiveFrom: form.effectiveFrom, publisherId: store.account?.id } : actionName === 'retire' ? { status: 'RETIRED', retiredBy: store.account?.id } : { status: 'UNDER_REVIEW', submitterId: store.account?.id }; await myotaClient.patchAward(selected.value.id, body); message.value = `Award ${actionName === 'publish' ? 'published' : `${actionName}ed`}.`; await load(selected.value.id); } catch (error) { message.value = error instanceof Error ? error.message : 'Award action failed.'; } }
function selectAssetFile(event: Event): void { assetFile.value = (event.target as HTMLInputElement).files?.[0] || null; if (assetFile.value) { assetForm.name ||= assetFile.value.name; assetForm.mediaType = assetFile.value.type || assetForm.mediaType; } }
function base64(buffer: ArrayBuffer): string { let binary = ''; const bytes = new Uint8Array(buffer); for (let index = 0; index < bytes.length; index += 0x8000) binary += String.fromCharCode(...bytes.subarray(index, Math.min(index + 0x8000, bytes.length))); return btoa(binary); }
async function registerAsset(): Promise<void> { try { const asset = await apiRequest<any>('/v1/awards/assets', { method: 'POST', body: JSON.stringify({ kind: assetForm.kind, name: assetForm.name, objectKey: assetForm.objectKey, mediaType: assetForm.mediaType, widthPx: Number(assetForm.width), heightPx: Number(assetForm.height), sha256: assetForm.sha256 || undefined }) }); if (assetFile.value) { try { const upload = await apiRequest<{ url: string }>(`/v1/awards/assets/${encodeURIComponent(asset.id)}/upload-url`, { method: 'POST', body: '{}' }); const response = await fetch(upload.url, { method: 'PUT', headers: { 'Content-Type': assetFile.value.type || 'application/octet-stream' }, body: assetFile.value }); if (!response.ok) throw new Error('Direct object upload failed.'); } catch { if (assetFile.value.size > 700000) throw new Error('Asset metadata was saved, but the fallback upload is limited to 700 KB. Configure a browser-reachable SeaweedFS upload URL.'); await apiRequest(`/v1/awards/assets/${encodeURIComponent(asset.id)}/content`, { method: 'POST', body: JSON.stringify({ contentBase64: base64(await assetFile.value.arrayBuffer()) }) }); } } message.value = 'Image asset registered.'; Object.assign(assetForm, { name: '', objectKey: '', sha256: '' }); assetFile.value = null; await load(); } catch (error) { message.value = error instanceof Error ? error.message : 'Unable to register asset.'; } }
watch(programme, () => { store.currentProgramme = programme.value; load(); }); onMounted(() => load());
</script>

<template>
  <section class="page-heading"><div><p class="eyebrow">ACTIVITY & CERTIFICATES</p><h1>Awards and certificates</h1><p class="muted">Programme-owned hunter and activator awards with explicit publication and print profiles.</p></div><button class="primary" @click="edit(null)">New award draft</button></section>
  <div class="toolbar"><label class="toolbar-field">Programme<select v-model="programme"><option v-for="item in store.programmes" :key="item.slug" :value="item.slug">{{ item.name }}</option></select></label><button class="secondary" @click="() => load()">Refresh</button></div>
  <div v-if="message" class="notice" role="status">{{ message }}</div>
  <div class="split-layout"><article class="panel"><div class="panel-heading"><h2>Award definitions</h2></div><div class="table-list"><button v-for="item in items" :key="item.id" class="table-row" :class="{ selected: selected?.id === item.id }" @click="edit(item)"><span><strong>{{ item.name }}</strong><small>{{ item.code }} · {{ item.category }} · {{ item.programmeSlug }}</small></span><span class="status-pill" :class="(item.status || '').toLowerCase()">{{ item.status }}</span></button><p v-if="!items.length" class="muted empty">No awards configured for this programme.</p></div></article><article class="panel"><div class="panel-heading"><h2>{{ selected ? selected.name : 'New award draft' }}</h2></div><form class="form-grid" @submit.prevent="save"><label>Code<input v-model="form.code" required></label><label>Name<input v-model="form.name" required></label><label>Category<select v-model="form.category"><option>HUNTER</option><option>ACTIVATOR</option></select></label><label>Achievement metric<select v-model="form.achievementMetric"><option>QSO_COUNT</option><option>ACTIVATION_COUNT</option><option>UNIQUE_CALLSIGNS</option><option>UNIQUE_ENTITIES</option></select></label><label class="wide">Description<textarea v-model="form.description"></textarea></label><label>Effective from<input v-model="form.effectiveFrom" type="datetime-local"></label><label>Background object key<input v-model="form.backgroundKey" placeholder="awards/programme/background.png"></label><label>Background width<input v-model.number="form.width" type="number" min="1"></label><label>Background height<input v-model.number="form.height" type="number" min="1"></label><label>Page<select v-model="form.page"><option>A4</option><option>LETTER</option></select></label><label>Orientation<select v-model="form.orientation"><option>PORTRAIT</option><option>LANDSCAPE</option></select></label><label>Resolution<input v-model.number="form.dpi" type="number" min="150"></label><label class="wide">Condition JSON<textarea v-model="form.condition" class="code-editor"></textarea><small class="field-help">Programme-owned AND / OR condition tree.</small></label><label class="wide">Levels JSON<textarea v-model="form.levels" class="code-editor"></textarea><small class="field-help">Incremental thresholds such as 10, 50 and 100.</small></label><div class="form-actions wide"><button class="primary" type="submit">Save award draft</button><button v-if="selected && ['DRAFT','CHANGES_REQUESTED'].includes(selected.status || '')" class="secondary" type="button" @click="action('submit')">Submit for review</button><button v-if="selected?.status === 'UNDER_REVIEW'" class="approve" type="button" @click="action('review', 'APPROVED')">Approve</button><button v-if="selected?.status === 'UNDER_REVIEW'" class="reject" type="button" @click="action('review', 'CHANGES_REQUESTED')">Request changes</button><button v-if="selected?.status === 'APPROVED'" class="primary" type="button" @click="action('publish')">Publish</button></div></form></article></div>
  <article class="panel"><div class="panel-heading"><div><p class="eyebrow">CERTIFICATE LAYOUT</p><h2>WYSIWYG placement</h2><p class="muted">Drag certificate fields over the print background, or fine-tune their normalized coordinates below.</p></div><button class="secondary" @click="addTemplateElement">Add text element</button></div><div class="award-layout"><div class="award-canvas" @pointermove="moveDrag" @pointerup="endDrag" @pointercancel="endDrag"><div class="award-canvas-background">{{ form.page }} · {{ form.orientation }} · {{ form.dpi }}</div><div v-for="(element, index) in templateElements" :key="element.kind + element.label" class="award-canvas-element" :style="{ left: `${element.x * 100}%`, top: `${element.y * 100}%`, width: `${element.width * 100}%`, height: `${element.height * 100}%` }" @pointerdown.stop="beginDrag($event, index)">{{ element.label }}</div></div><div class="award-elements"><div v-for="(element, index) in templateElements" :key="`${element.kind}-${index}`" class="award-element-row"><input v-model="element.label" aria-label="Element label"><label>X<input v-model.number="element.x" type="number" min="0" max="1" step=".01"></label><label>Y<input v-model.number="element.y" type="number" min="0" max="1" step=".01"></label><label>W<input v-model.number="element.width" type="number" min=".01" max="1" step=".01"></label><label>H<input v-model.number="element.height" type="number" min=".01" max="1" step=".01"></label><button class="quiet" type="button" @click="removeTemplateElement(index)">Remove</button></div></div></div></article>
  <div class="dashboard-grid"><article class="panel"><div class="panel-heading"><div><h2>Registered assets</h2><small class="muted">{{ assets.length }} image assets</small></div></div><div class="table-list"><div v-for="asset in assets" :key="asset.id" class="table-row"><span><strong>{{ asset.name }}</strong><small>{{ asset.kind }} · {{ asset.objectKey }}</small></span><span>{{ asset.widthPx }} × {{ asset.heightPx }} px</span></div></div></article><article class="panel"><div class="panel-heading"><h2>Requests and issuances</h2></div><div class="table-list"><div v-for="request in requests" :key="request.id" class="table-row"><span><strong>{{ request.callsign }} · {{ request.personName }}</strong><small>{{ request.programmeSlug }} · {{ request.levelId }}</small></span><span class="status-pill">{{ request.status }}</span></div><div v-for="issuance in issuances" :key="issuance.id" class="table-row"><span><strong>{{ issuance.awardName }}</strong><small>{{ issuance.callsign }} · {{ issuance.levelId }}</small></span><span>{{ issuance.dateObtained }}</span></div><p v-if="!requests.length && !issuances.length" class="muted empty">No requests or issuances yet.</p></div></article></div>
  <article class="panel"><div class="panel-heading"><div><p class="eyebrow">ASSET MANAGEMENT</p><h2>Register signature or background</h2><p class="muted">The binary is uploaded to SeaweedFS through a short-lived object URL when available.</p></div></div><form class="form-grid" @submit.prevent="registerAsset"><label>Asset type<select v-model="assetForm.kind"><option>SIGNATURE</option><option>BACKGROUND</option></select></label><label>Display name<input v-model="assetForm.name" required></label><label>Object key<input v-model="assetForm.objectKey" placeholder="signatures/manager.png" required></label><label>Media type<input v-model="assetForm.mediaType" required></label><label>Width<input v-model.number="assetForm.width" type="number" min="1" required></label><label>Height<input v-model.number="assetForm.height" type="number" min="1" required></label><label class="wide">Image file<input type="file" accept="image/*" @change="selectAssetFile"></label><label class="wide">SHA-256 checksum<input v-model="assetForm.sha256"></label><div class="form-actions wide"><button class="primary" type="submit">Register image asset</button></div></form></article>
</template>
